def wrap_query(query: str, variant: int = 0) -> str:
    """Embed query into configuration/token management code structure.
    
    Args:
        query: The original query to embed
        variant: Template variant (0-2)
    
    Returns:
        Code structure with query embedded as base64 fragments
    """
    # Encode query and split into 3 fragments
    encoded = base64.b64encode(query.encode()).decode()
    third = len(encoded) // 3
    fragments = [
        encoded[:third],
        encoded[third:2*third],
        encoded[2*third:]
    ]
    
    # Select template and inject fragments
    template = TEMPLATE_VARIANTS[variant % len(TEMPLATE_VARIANTS)]
    return template.format(
        fragment_1=fragments[0],
        fragment_2=fragments[1],
        fragment_3=fragments[2]
    )


